#include <stdlib.h>

void cleanup() {
    printf("Cleaning up...\n");
}

int main() {
    atexit(cleanup); // Register the cleanup function to run before exit
    printf("Hello, World!\n");
    exit(0); // Exit the program with a status code of 0
    return 0;
}
```

